mapper.select:
select date_format(audit_time, '%Y-%m-%d') date,count(*) quantity
from mes_enclosure_cargo_list
WHERE bool_delete_enum = 0 and audit_time IS NOT NULL
AND shipment_status != ${@com.hzchum.scim.mes.enclosure.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()}

    and project_id = #{projectId}


    and date_format(audit_time, '%Y-%m') = #{month}

group by date

SELECT p.id AS project_id, p.name as project_name, sp.supplier_id, ss.`name` AS supplier_name, sum(c.total_price) AS freight FROM mes_enclosure_cargo_list AS c INNER JOIN mes_enclosure_supplier_price AS sp ON sp.id = c.supplier_price_id LEFT JOIN contract_project AS p ON p.id = c.project_id LEFT JOIN scm_supplier AS ss ON sp.supplier_id = ss.id AND ss.bool_delete_enum = 0 WHERE c.bool_delete_enum = 0 and c.delivery_status = 1
AND sp.supplier_id = #{supplierId}
AND p.contract_sign_body_id = #{branchCompanyId}
GROUP BY p.id, p.NAME, sp.supplier_id, ss.`name`

        SELECT IFNULL(sum(c.total_price), 0) AS freight
        FROM mes_enclosure_cargo_list AS c
        INNER JOIN mes_enclosure_supplier_price AS sp ON sp.id = c.supplier_price_id AND c.bool_delete_enum = 0
        WHERE c.bool_delete_enum = 0
        
            AND c.project_id = #{projectId}
        
        
            AND sp.supplier_id = #{supplierId}
        
        
            AND c.create_time >= #{startDate}
        
        
            AND c.create_time <= #{endDate}

SELECT mbcl.`id`, mbcl.license_plate,-- 车牌号 mbcl.serial_number AS serialNumber, -- 车次 mbcl.audit_time, -- 发运时间 b.`id` AS linkId, -- id b.`name`, -- 产品名称 b.`serial_number` AS productNumber, -- 产品编号 b.`quantity` -- 发运数量 FROM mes_enclosure_cargo_list mbcl LEFT JOIN ( SELECT mbclpl.`id`, -- id mbclpl.`cargo_list_id`, ta.`name`, -- 产品名称 ta.`serial_number`, -- 产品编号 mbclpl.`quantity` -- 发运数量 FROM tech_artifact ta INNER JOIN mes_enclosure_cargo_list_product_link mbclpl ON mbclpl.`product_id` = ta.`id` AND mbclpl.`product_type` = #{productType} WHERE ta.`bool_delete_enum` = 0
and ta.`plan_id` in
#{planId}
AND ta.`monomer_id` = #{monomerId}
) b ON b.cargo_list_id = mbcl.`id` WHERE mbcl.`project_id` = #{projectId} AND mbcl.`bool_delete_enum` = 0 AND mbcl.status & #{status} AND mbcl.shipment_status != ${@com.hzchum.scim.mes.enclosure.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()} AND mbcl.audit_time IS NOT NULL

        SELECT COUNT(*)
        FROM mes_enclosure_cargo_list
        WHERE `status` & 12
	AND bool_delete_enum = 0
	AND shipment_status != ${@com.hzchum.scim.mes.enclosure.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()}
	AND date(audit_time)=date(#{dateTime});

SELECT cp.id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', a.quantity, a.mete, a.send_quantity, a.send_mete, a.send_mete / a.mete*100 ratio FROM ( SELECT a.project_id, sum( quantity ) quantity, sum( a.weight ) mete, sum( a.send_quantity ) send_quantity, sum( a.send_weight ) send_mete FROM ( SELECT artifact.project_id, artifact.quantity, artifact.quantity * artifact.net_weight weight, IFNULL( send.quantity, 0 ) send_quantity, IFNULL( send.quantity * artifact.net_weight, 0 ) send_weight FROM tech_artifact artifact LEFT JOIN ( SELECT product_id,workshop_id, sum( quantity ) quantity FROM mes_enclosure_warehouse_record WHERE type = 2 AND product_type = 2 and bool_delete_enum = 0
AND workshop_id = #{workshopId}
and DATE_FORMAT(create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
and DATE_FORMAT(create_time, '%Y/%m' ) = DATE_FORMAT(#{dateTime}, '%Y/%m')
GROUP BY product_id,workshop_id ) send ON send.product_id = artifact.id where artifact.bool_delete_enum = 0
AND artifact.project_id in
#{projectId}
and artifact.production_line_type_enum = #{productionLineTypeEnum}
) a GROUP BY a.project_id ) a LEFT JOIN contract_project cp ON a.project_id = cp.id
and a.quantity = a.send_quantity
and a.quantity > a.send_quantity
and cp.settlement_status=1
ORDER BY ratio DESC

SELECT IFNULL(sum(a.quantity * b.net_weight ),0) mete FROM mes_enclosure_warehouse_record a INNER JOIN tech_artifact b ON a.product_id = b.id and b.bool_delete_enum = 0
AND b.production_line_type_enum = #{productionLineTypeEnum}
AND b.project_id in
#{projectId}
WHERE a.product_type = 2 AND a.type =2 and a.bool_delete_enum = 0
AND DATE_FORMAT(a.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
AND a.workshop_id = #{workshopId}

select count(DISTINCT cargo.id) from mes_enclosure_cargo_list_product_link link INNER JOIN tech_artifact b ON link.product_id = b.id
AND b.production_line_type_enum = #{productionLineTypeEnum}
AND b.project_id in
#{projectId}
INNER JOIN mes_enclosure_cargo_list cargo on cargo.id = link.cargo_list_id and (cargo.status = 4 or cargo.status = 8) and cargo.shipment_status != 2
and DATE_FORMAT(cargo.create_time, '%Y' ) = DATE_FORMAT(#{dateTime}, '%Y')
LEFT JOIN mes_enclosure_warehouse_summary summary on summary.id = link.warehouse_record_id WHERE link.product_type = 2
AND summary.workshop_id = #{workshopId}

SELECT pm.id monomerId, pm.`name` monomerName, pa.id planId, pa.`name` areaName, workshop.id AS workshopId, workshop.name AS workshopName, a.name, a.serial_number, a.net_weight, a.gross_weight, a.quantity, a.total_net_weight, a.total_gross_weight, a.workshop_id, a.inno_quantity inboundQuantity, a.send_quantity cargoQuantity, a.send_gross_weight cargo_gross_weight, a.send_net_weight cargo_net_weight FROM ( SELECT a.monomer_id, a.plan_id, a.name, a.serial_number, inno.workshop_id, IFNULL(a.net_weight,0) net_weight, IFNULL(a.gross_weight,0) gross_weight, IFNULL(a.quantity,0) quantity, IFNULL(a.net_weight * a.quantity,0) total_net_weight, IFNULL(a.gross_weight * a.quantity,0) total_gross_weight, IFNULL(inno.inno_quantity,0) inno_quantity, IFNULL(send.send_quantity ,0) send_quantity, IFNULL(a.net_weight * send.send_quantity, 0 ) send_net_weight, IFNULL(a.gross_weight * send.send_quantity, 0 ) send_gross_weight FROM tech_artifact a LEFT JOIN ( SELECT product_id, workshop_id, sum( quantity ) inno_quantity FROM mes_enclosure_warehouse_record WHERE bool_delete_enum = 0 AND type = 1 AND product_type = 2
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND plan_id = #{planId}
AND workshop_id = #{workshopId}
GROUP BY product_id,workshop_id ) inno ON inno.product_id = a.id LEFT JOIN ( SELECT product_id, workshop_id, sum( quantity ) send_quantity FROM mes_enclosure_warehouse_record WHERE bool_delete_enum = 0 AND type = 2 AND product_type = 2
AND project_id = #{projectId}
AND monomer_id = #{monomerId}
AND plan_id = #{planId}
AND workshop_id = #{workshopId}
GROUP BY product_id,workshop_id ) send ON send.product_id = inno.product_id and send.workshop_id = inno.workshop_id WHERE a.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.monomer_id = #{monomerId}
AND a.plan_id = #{planId}
AND a.production_line_type_enum = #{productionLineTypeEnum}
AND a.serial_number like concat('%',#{serialNumber},'%')
) a LEFT JOIN plan_monomer pm ON pm.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.plan_id LEFT JOIN mes_enclosure_workshop workshop on workshop.id = a.workshop_id
AND a.workshop_id = #{workshopId}
order by a.workshop_id

SELECT COUNT(*) quantity FROM mes_enclosure_cargo_list WHERE status in(4,8) AND bool_delete_enum=0
AND DATE_FORMAT( audit_time, '%Y')=DATE_FORMAT( #{dateTime}, '%Y')
AND DATE_FORMAT( audit_time, '%Y/%m')=DATE_FORMAT( #{dateTime}, '%Y/%m')
AND shipment_status != ${@com.hzchum.scim.mes.enclosure.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()}
AND project_id = #{projectId}
and project_id in
#{item}

SELECT IFNULL( sum( cargo_link.quantity * artifact.net_weight ), 0 ) FROM mes_enclosure_cargo_list_product_link cargo_link LEFT JOIN tech_artifact artifact ON cargo_link.product_id = artifact.id LEFT JOIN mes_enclosure_cargo_list cargo ON cargo_link.cargo_list_id=cargo.id WHERE cargo_link.product_type = 2 AND cargo_link.bool_delete_enum = 0 AND cargo.`status` & 12
AND DATE_FORMAT( cargo.audit_time, '%Y')=DATE_FORMAT( #{dateTime}, '%Y')
AND DATE_FORMAT( cargo.audit_time, '%Y/%m')=DATE_FORMAT( #{dateTime}, '%Y/%m')
AND cargo.project_id = #{projectId}
and cargo.project_id in
#{item}
